"""Contenido original R9. Datos, explicaciones y procedimientos explícitos; sin IA.
Alcance: fundamentos. No sustituye construcciones geométricas ni simulacros oficiales.
"""
import json
from pathlib import Path
U=[]
def a(q,answer,steps,wrong=None):
 answer=str(answer)
 if wrong is None:wrong=[str(int(answer)+1),str(int(answer)+10)]
 opts=list(dict.fromkeys([answer,*map(str,wrong)]));assert len(opts)>1,q
 return dict(enunciado=q,respuesta_correcta=answer,opciones=opts,paso_resuelto=steps,visual=None)
def unit(id,topic,title,explanation,example,steps,hint,activities):
 assert len(activities)==6,id
 for i,x in enumerate(activities):
  x['id']=id+'-v'+str(i+1);k=i%len(x['opciones']);x['opciones']=x['opciones'][k:]+x['opciones'][:k]
 U.append(dict(id=id,tema=topic,titulo=title,explicacion=explanation,ejemplo=example,pasos=steps,pista=hint,visual=None,actividades=activities))
t='numeros_naturales_sistema_decimal'
unit('mat_num_decenas',t,'Diez unidades forman una decena','Podemos contar objetos formando paquetes de diez. Cada paquete es una decena. Los objetos que no completan un paquete quedan como unidades.','23 fichas son 2 decenas y 3 unidades.',['Formamos dos paquetes de diez: 20 fichas.','Quedan 3 fichas sueltas: 20 + 3 = 23.'],'Separá los paquetes completos de las unidades sueltas.',[a(f'Tenés {n} fichas. ¿Cuántas decenas completas podés formar?',n//10,f'Formamos {n//10} paquetes de 10; quedan {n%10} fichas sueltas.',[n%10,n]) for n in [23,34,45,56,67,78]])
unit('mat_num_posicion',t,'El lugar de cada cifra','De derecha a izquierda están unidades, decenas y centenas. Un cero conserva un lugar vacío. En 304 hay 3 centenas, ninguna decena y 4 unidades.','En 352, el 5 vale 50 porque ocupa las decenas.',['Leemos 3 centenas, 5 decenas y 2 unidades.','Descomponemos: 300 + 50 + 2 = 352.'],'Contá las posiciones desde la derecha.',[a(f'En {n}, ¿cuánto vale la cifra {str(n)[-2]} de las decenas?',int(str(n)[-2])*10,f'Hay {str(n)[-2]} decenas: {str(n)[-2]} × 10 = {int(str(n)[-2])*10}.',[int(str(n)[-2]),int(str(n)[-2])*100,100]) for n in [352,426,571,683,794,208]])
unit('mat_num_orden',t,'Comparar desde el lugar más grande','Para comparar números naturales, miramos primero cuántas cifras tienen. Con igual cantidad de cifras, comparamos desde la izquierda. Si son iguales, seguimos a la siguiente posición.','418 es mayor que 391.',['Ambos tienen tres cifras.','418 tiene 4 centenas y 391 tiene 3: elegimos 418.'],'Compará centenas antes que decenas y unidades.',[a(f'¿Cuál es mayor: {x} o {y}?',max(x,y),f'Al comparar de izquierda a derecha, {max(x,y)} es mayor que {min(x,y)}.',[min(x,y)]) for x,y in [(418,391),(507,570),(632,623),(804,480),(109,190),(725,752)]])
unit('mat_num_suma',t,'Sumar y reagrupar','Sumar reúne cantidades. Alineamos unidades con unidades y decenas con decenas. Si juntamos diez unidades, las cambiamos por una decena.','27 + 15 = 42.',['7 + 5 = 12: una decena y 2 unidades.','2 + 1 + 1 decenas = 4 decenas; quedan 42.'],'Si las unidades llegan a diez, llevá una decena.',[a(f'Tenés {x} fichas y recibís {y}. ¿Cuántas tenés ahora?',x+y,f'Unidades: {x%10} + {y%10} = {x%10+y%10}.\nSumamos también las decenas: {x} + {y} = {x+y}.') for x,y in [(27,15),(36,18),(48,24),(56,27),(19,34),(65,28)]])
unit('mat_num_resta',t,'Restar y comprobar','Restar permite saber cuánto queda. Si faltan unidades para quitar, cambiamos una decena por diez unidades. Podemos comprobar sumando lo que quitamos a lo que quedó.','42 − 17 = 25.',['42 son también 3 decenas y 12 unidades.','12 − 7 = 5 y 3 − 1 = 2 decenas. Comprobamos: 25 + 17 = 42.'],'Podés cambiar una decena por diez unidades.',[a(f'Había {x} fichas y usaste {y}. ¿Cuántas quedan?',x-y,f'Cambiamos una decena: {x//10-1} decenas y {x%10+10} unidades.\n{x} − {y} = {x-y}. Comprobamos: {x-y} + {y} = {x}.') for x,y in [(42,17),(53,28),(61,36),(74,49),(82,57),(95,68)]])
t='tablas_multiplicar_2_5'
unit('mat_tab_grupos',t,'Multiplicar cuenta grupos iguales','Una multiplicación abrevia una suma repetida. En 3 × 4 tenemos tres grupos de cuatro. Los números que multiplicamos se llaman factores y el resultado es el producto.','3 platos con 4 galletitas suman 12.',['Sumamos 4 + 4 + 4.','Escribimos 3 × 4 = 12.'],'Contá los grupos y cuánto hay en cada uno.',[a(f'Hay {x} platos con {y} galletitas en cada uno. ¿Cuántas hay en total?',x*y,' + '.join([str(y)]*x)+f' = {x*y}. Son {x} × {y}.',[x+y,x*y+y]) for x,y in [(3,4),(2,5),(4,3),(5,4),(3,5),(4,5)]])
unit('mat_tab_dobles',t,'Dobles y el orden de los factores','El doble es dos veces una cantidad. Para multiplicar por cuatro podemos hacer el doble del doble. Cambiar el orden de los factores conserva el total: 3 × 4 = 4 × 3.','4 × 3 = 12.',['El doble de 3 es 6.','El doble de 6 es 12: cuatro veces 3.'],'Calculá un doble y después otro doble.',[a(f'Calculá 4 × {n} usando dobles.',4*n,f'El doble de {n} es {2*n}.\nEl doble de {2*n} es {4*n}.') for n in [3,4,5,6,7,8]])
unit('mat_tab_cinco',t,'Contar de cinco en cinco','Cada grupo nuevo de cinco suma cinco al total. Los resultados de la tabla del cinco terminan en 0 o 5. Este patrón ayuda a comprobar, pero para saber el total contamos los grupos.','5 × 4 = 20.',['Contamos cuatro saltos: 5, 10, 15, 20.','Son cuatro grupos de cinco: 20.'],'Contá los saltos, además de mirar la última cifra.',[a(f'¿Cuánto es 5 × {n}?',5*n,', '.join(str(5*i) for i in range(1,n+1))+f': {n} grupos dan {5*n}.') for n in [4,3,6,7,8,9]])
t='tablas_multiplicar_6_8'
unit('mat_tab_seis_ocho',t,'Construir las tablas del seis y del ocho','Para multiplicar por seis duplicamos el resultado de multiplicar por tres. Para multiplicar por ocho duplicamos el resultado de multiplicar por cuatro. Podés escribir los pasos.','8 × 5 = 40.',['4 × 5 = 20.','Duplicamos: 20 + 20 = 40.'],'Buscá primero la tabla de la mitad del factor.',[a(f'Calculá {k} × {n} con un doble.',k*n,f'{k//2} × {n} = {k*n//2}.\nSu doble es {k*n}.') for k,n in [(8,5),(6,4),(8,3),(6,7),(8,6),(6,8)]])
unit('mat_tab_siete',t,'Siete grupos: cinco más dos','Podemos separar siete grupos en cinco grupos y dos grupos. Multiplicamos cada parte por la misma cantidad y sumamos los resultados.','7 × 6 = 42.',['5 × 6 = 30 y 2 × 6 = 12.','Sumamos 30 + 12 = 42.'],'Separá 7 en 5 + 2 sin cambiar el otro factor.',[a(f'Calculá 7 × {n}.',7*n,f'5 × {n} = {5*n}; 2 × {n} = {2*n}.\n{5*n} + {2*n} = {7*n}.') for n in [6,3,4,5,7,8]])
t='tablas_multiplicar_9_10'
unit('mat_tab_diez',t,'Multiplicar por diez cambia el valor','Al multiplicar un natural por diez, cada unidad pasa a valer una decena. Escribimos un cero a la derecha. Por cien, cada unidad pasa a valer una centena.','23 × 10 = 230.',['23 grupos de diez son 23 decenas.','23 decenas equivalen a 230 unidades.'],'Pensá en decenas para × 10 y centenas para × 100.',[a(f'¿Cuánto es {n} × {k}?',n*k,f'{n} grupos de {k} dan {n*k}.',[n+k,n*(k//10)]) for n,k in [(23,10),(14,10),(32,100),(7,100),(45,10),(16,100)]])
unit('mat_tab_nueve',t,'Nueve veces: diez veces menos una','Nueve grupos son diez grupos menos un grupo. Para calcular 9 × 6 hacemos 10 × 6 y quitamos 6, porque quitamos un grupo completo.','9 × 6 = 54.',['10 × 6 = 60.','Quitamos un grupo de 6: 60 − 6 = 54.'],'Restá el tamaño de un grupo, no el número uno.',[a(f'Calculá 9 × {n}.',9*n,f'10 × {n} = {10*n}.\n{10*n} − {n} = {9*n}.',[10*n-1,10*n]) for n in [6,3,4,5,7,8]])
t='division_1_digito'
unit('mat_div_repartir',t,'Repartir la misma cantidad','Dividir reparte un total en grupos iguales. El dividendo es el total; el divisor, la cantidad de grupos; el cociente, lo que recibe cada grupo. Nunca dividimos por cero.','12 fichas entre 3 personas: 4 para cada una.',['Buscamos qué número multiplicado por 3 da 12.','3 × 4 = 12; entonces 12 ÷ 3 = 4.'],'Buscá una multiplicación que reconstruya el total.',[a(f'Repartí {n} fichas entre {d} personas por igual. ¿Cuántas recibe cada una?',n//d,f'{d} × {n//d} = {n}; cada persona recibe {n//d}.') for n,d in [(12,3),(20,4),(18,3),(24,4),(35,5),(32,4)]])
unit('mat_div_resto',t,'Lo que sobra es el resto','Cuando no se puede repartir todo por igual, quedan elementos sin repartir: el resto. El resto debe ser menor que el divisor; de lo contrario todavía podríamos dar uno más a cada grupo.','17 fichas entre 3: 5 para cada una y sobran 2.',['3 × 5 = 15: repartimos 15.','17 − 15 = 2. El resto 2 es menor que 3.'],'Buscá el mayor múltiplo del divisor que no supere el total.',[a(f'Repartí {n} fichas entre {d} personas, todas reciben lo mismo. ¿Cuántas sobran?',n%d,f'{d} × {n//d} = {n-n%d}.\n{n} − {n-n%d} = {n%d}; ese es el resto.',[0,d]) for n,d in [(17,3),(22,4),(19,5),(26,4),(32,5),(29,3)]])
unit('mat_div_descomponer',t,'Dividir en partes conocidas','Podemos separar el total en dos cantidades que sepamos repartir. Dividimos ambas por el mismo divisor y sumamos sus cocientes.','84 ÷ 4 = 21.',['80 ÷ 4 = 20 y 4 ÷ 4 = 1.','20 + 1 = 21; comprobamos 21 × 4 = 84.'],'Separá una parte grande que puedas dividir y repartí lo que queda.',[a(f'Calculá {x+y} ÷ {d}.',(x+y)//d,f'{x} ÷ {d} = {x//d}; {y} ÷ {d} = {y//d}.\n{x//d} + {y//d} = {(x+y)//d}.') for x,y,d in [(80,4,4),(60,9,3),(80,12,4),(100,15,5),(60,12,3),(40,16,4)]])
t='numeros_romanos'
unit('mat_rom_sumar',t,'Leer símbolos romanos que suman','I vale 1, V vale 5, X vale 10, L vale 50, C vale 100, D vale 500 y M vale 1000. Si los símbolos van de mayor a menor, sumamos. I, X, C y M pueden repetirse hasta tres veces seguidas.','XVI representa 16.',['X vale 10, V vale 5 e I vale 1.','10 + 5 + 1 = 16.'],'Sumá cuando los símbolos van de mayor a menor.',[a(f'¿Qué número representa {r}?',n,steps) for r,n,steps in [('XVI',16,'10 + 5 + 1 = 16.'),('VIII',8,'5 + 1 + 1 + 1 = 8.'),('XXI',21,'10 + 10 + 1 = 21.'),('LX',60,'50 + 10 = 60.'),('CXV',115,'100 + 10 + 5 = 115.'),('DII',502,'500 + 1 + 1 = 502.')]])
unit('mat_rom_restar',t,'Los seis pares que restan','Solo usamos estos pares para restar: IV = 4, IX = 9, XL = 40, XC = 90, CD = 400 y CM = 900. En cada par el símbolo pequeño se resta del grande. No podemos inventar cualquier pareja.','XIV representa 14.',['Separamos X y IV.','X vale 10; IV vale 5 − 1 = 4. Total: 14.'],'Buscá primero uno de los seis pares permitidos.',[a(f'¿Qué número representa {r}?',n,steps) for r,n,steps in [('XIV',14,'10 + (5 − 1) = 14.'),('XIX',19,'10 + (10 − 1) = 19.'),('XLII',42,'(50 − 10) + 2 = 42.'),('XCIII',93,'(100 − 10) + 3 = 93.'),('CDV',405,'(500 − 100) + 5 = 405.'),('CMVI',906,'(1000 − 100) + 6 = 906.')]])
t='fracciones_del_resto'
unit('mat_resto_entero',t,'Primero averiguamos cuánto queda','El resto es lo que queda después de usar una parte. Calculamos esa parte y la restamos del entero. El entero de referencia debe estar claro.','De 24 fichas usamos 1/3. Quedan 16.',['24 ÷ 3 = 8: usamos 8 fichas.','24 − 8 = 16: ese es el resto.'],'Calculá lo usado antes de restarlo del total.',[a(f'De {n} fichas usás 1/{d}. ¿Cuántas quedan?',n-n//d,f'Usamos {n} ÷ {d} = {n//d}.\nQuedan {n} − {n//d} = {n-n//d}.') for n,d in [(24,3),(20,4),(30,5),(18,3),(32,4),(40,5)]])
unit('mat_resto_nuevo_total',t,'Una fracción de lo que quedó','Si una consigna dice «del resto», la segunda fracción se calcula sobre lo que quedó, no sobre el total inicial. Escribimos las cantidades de cada etapa.','De 24 fichas usamos 1/3; después, la mitad del resto. En la segunda etapa usamos 8.',['Primero usamos 8 y quedan 16.','La mitad del resto es 16 ÷ 2 = 8.'],'Encerrá el resto: ese es el nuevo total para el segundo cálculo.',[a(f'Tenés {n} fichas. Usás 1/{d} del total y después la mitad del resto. ¿Cuántas usás en la segunda etapa?',(n-n//d)//2,f'Primero: {n} ÷ {d} = {n//d}; quedan {n-n//d}.\nSegunda etapa: {n-n//d} ÷ 2 = {(n-n//d)//2}.',[n//2,n//d,n]) for n,d in [(24,3),(40,5),(32,4),(36,3),(48,4),(60,5)]])
def dec(n):return f'{n/10:.1f}'.replace('.',',')
t='decimales_conversion'
unit('mat_dec_fraccion',t,'Décimos y centésimos','A la derecha de la coma, la primera cifra cuenta décimos y la segunda centésimos. 0,3 son tres décimos; 0,03 son tres centésimos. El denominador indica las partes iguales de la unidad.','7/10 se escribe 0,7.',['El denominador 10 indica décimos.','Ponemos 7 en el lugar de los décimos: 0,7.'],'Contá cuántas posiciones necesitás después de la coma.',[a(f'Escribí {n}/{d} como decimal.',f'0,{n}' if d==10 else f'0,{n:02d}',f'El denominador es {d}; usamos '+('una cifra' if d==10 else 'dos cifras')+' después de la coma.',[f'{n},0',f'0,{n:02d}' if d==10 else f'{n},00']) for n,d in [(7,10),(3,100),(5,10),(25,100),(8,100),(42,100)]])
unit('mat_dec_sumar',t,'Sumar decimales alineando la coma','Al sumar decimales juntamos unidades con unidades y décimos con décimos. Podemos escribir ceros al final de la parte decimal sin cambiar el valor.','1,2 + 0,5 = 1,7.',['Son 12 décimos más 5 décimos.','17 décimos equivalen a 1,7.'],'Alineá las comas antes de sumar.',[a(f'Calculá {dec(x)} + {dec(y)}.',dec(x+y),f'{x} décimos + {y} décimos = {x+y} décimos: {dec(x+y)}.',[dec(x+y+10),dec(x+y+1)]) for x,y in [(12,5),(24,13),(36,18),(47,25),(59,12),(63,29)]])
unit('mat_dec_restar',t,'Restar decimales','Restamos cantidades de la misma posición: décimos con décimos, unidades con unidades. Si lo necesitás, expresá todo en décimos antes de calcular.','2,4 − 0,7 = 1,7.',['24 décimos menos 7 décimos son 17 décimos.','17 décimos equivalen a 1,7.'],'Alineá las comas y comprobá sumando.',[a(f'Calculá {dec(x)} − {dec(y)}.',dec(x-y),f'{x} − {y} = {x-y} décimos: {dec(x-y)}.',[dec(x+y),dec(x-y+1)]) for x,y in [(24,7),(35,8),(46,19),(57,28),(68,39),(79,45)]])
unit('mat_dec_producto',t,'Multiplicar decimales por un natural','Multiplicar por un natural reúne grupos iguales, también con decimales. Si cada botella contiene 0,5 litros, tres botellas contienen tres veces esa cantidad.','3 × 0,5 = 1,5.',['0,5 + 0,5 + 0,5 suma 15 décimos.','15 décimos son 1,5.'],'Contá los décimos de todos los grupos.',[a(f'Hay {k} botellas de {dec(n)} litros cada una. ¿Cuántos litros hay?',dec(k*n),f'{k} × {n} décimos = {k*n} décimos: {dec(k*n)} litros.',[dec(k*n+1),str(k*n)]) for k,n in [(3,5),(4,2),(2,7),(5,3),(3,8),(4,6)]])
unit('mat_dec_dividir',t,'Repartir una cantidad decimal','Dividir una cantidad decimal entre un natural reparte partes iguales. Podemos convertir la cantidad a décimos, repartirlos y volver a escribir el decimal.','1,8 litros en 3 botellas: 0,6 litros en cada una.',['1,8 litros son 18 décimos.','18 ÷ 3 = 6 décimos; cada botella recibe 0,6 litros.'],'Repartí los décimos y conservá la unidad.',[a(f'Repartís {dec(n)} litros por igual en {d} botellas. ¿Cuántos litros van en cada botella?',dec(n//d),f'{n} décimos ÷ {d} = {n//d} décimos: {dec(n//d)} litros.',[str(n//d),dec(n//d+1)]) for n,d in [(18,3),(24,4),(35,5),(28,4),(36,3),(45,5)]])
t='potenciacion_y_raiz_cuadrada'
unit('mat_pot_repetir',t,'Una potencia repite factores','En 3², el 3 es la base y el 2 es el exponente. El exponente dice cuántas veces aparece la base como factor. 3² es 3 × 3, no 3 × 2.','2³ = 2 × 2 × 2 = 8.',['Escribimos tres factores iguales a 2.','2 × 2 = 4; 4 × 2 = 8.'],'El exponente cuenta factores.',[a(f'Calculá {n} elevado a {e}.',n**e,' × '.join([str(n)]*e)+f' = {n**e}.',[n*e,n**e+1]) for n,e in [(2,3),(3,2),(4,2),(3,3),(5,2),(6,2)]])
unit('mat_raiz_cuadrado',t,'La raíz busca el lado del cuadrado','La raíz cuadrada busca el número no negativo que, multiplicado por sí mismo, da el total. Con fichas, podemos imaginar un cuadrado con igual cantidad de filas y columnas.','La raíz cuadrada de 25 es 5.',['5 filas de 5 fichas forman 25 fichas.','Como 5 × 5 = 25, la raíz cuadrada de 25 es 5.'],'Buscá dos factores iguales cuyo producto sea el total.',[a(f'¿Cuál es la raíz cuadrada de {n*n}?',n,f'{n} × {n} = {n*n}. La raíz cuadrada es {n}.') for n in [5,3,4,6,7,8]])
t='jerarquia_operaciones'
unit('mat_jer_producto',t,'Antes de sumar, resolvemos los productos','Primero resolvemos potencias y raíces; después multiplicaciones y divisiones; al final sumas y restas. Entre operaciones del mismo nivel avanzamos de izquierda a derecha.','2 + 3 × 4 = 14.',['Primero 3 × 4 = 12.','Después 2 + 12 = 14.'],'Marcá el producto antes de sumar.',[a(f'Calculá {x} + {y} × {z}.',x+y*z,f'Primero {y} × {z} = {y*z}.\nDespués {x} + {y*z} = {x+y*z}.',[(x+y)*z,x+y+z]) for x,y,z in [(2,3,4),(3,4,5),(4,2,6),(5,3,7),(6,4,3),(7,2,8)]])
unit('mat_jer_parentesis',t,'Los paréntesis indican por dónde empezar','Un paréntesis agrupa una cuenta que debemos resolver primero. Después seguimos el orden de operaciones. Copiar la cuenta reemplazando solo el paso resuelto ayuda a no perder números.','(2 + 3) × 4 = 20.',['Dentro del paréntesis: 2 + 3 = 5.','Ahora 5 × 4 = 20.'],'Resolvé el grupo entre paréntesis antes de seguir.',[a(f'Calculá ({x} + {y}) × {z}.',(x+y)*z,f'Primero {x} + {y} = {x+y}.\nDespués {x+y} × {z} = {(x+y)*z}.',[x+y*z,x+y+z]) for x,y,z in [(2,3,4),(3,4,5),(4,2,6),(5,3,7),(6,4,3),(7,2,8)]])
t='si_me_la_longitud'
unit('mat_long_metros',t,'El metro y el centímetro','Medir una longitud es compararla con una unidad. Un metro contiene 100 centímetros. Al pasar de metros a centímetros usamos más unidades pequeñas para expresar la misma longitud.','2 m = 200 cm.',['Cada metro contiene 100 centímetros.','2 × 100 = 200 centímetros.'],'La longitud no cambia; cambia la unidad.',[a(f'¿Cuántos centímetros son {n} metros?',n*100,f'{n} × 100 = {n*100} cm.',[n*10,n+100]) for n in [2,3,4,5,6,7]])
unit('mat_long_combinar',t,'Sumar longitudes con la misma unidad','Antes de sumar medidas, las expresamos en la misma unidad. 1 km = 1000 m; 1 m = 100 cm y 1 cm = 10 mm. No sumamos directamente números de unidades distintas.','1 m y 25 cm suman 125 cm.',['1 m = 100 cm.','100 cm + 25 cm = 125 cm.'],'Convertí las medidas a la unidad que pide la pregunta.',[a(f'Una cinta mide {m} m y {c} cm. ¿Cuántos centímetros mide en total?',m*100+c,f'{m} m = {m*100} cm.\n{m*100} + {c} = {m*100+c} cm.',[m+c,m*10+c]) for m,c in [(1,25),(2,30),(3,45),(4,50),(5,75),(6,20)]])
t='si_me_la_masa_capacidad_tiempo'
unit('mat_med_masa_capacidad',t,'Mil partes: gramos y mililitros','Un kilogramo contiene 1000 gramos. Un litro contiene 1000 mililitros. Son dos equivalencias distintas: la masa y la capacidad no se convierten entre sí usando esta regla.','2 kg = 2000 g; 3 L = 3000 mL.',['Elegimos la magnitud: masa o capacidad.','Multiplicamos por 1000 para pasar a gramos o mililitros.'],'Conservá la magnitud y escribí la unidad pedida.',[a(f'¿Cuántos {small} son {n} {big}?',n*1000,f'Cada {big} contiene 1000 {small}.\n{n} × 1000 = {n*1000} {small}.',[n*100,n+1000]) for n,big,small in [(2,'kg','g'),(3,'L','mL'),(4,'kg','g'),(5,'L','mL'),(6,'kg','g'),(7,'L','mL')]])
unit('mat_med_tiempo',t,'Una hora tiene sesenta minutos','El tiempo no sigue los saltos de diez de las medidas anteriores. Una hora tiene 60 minutos y un minuto tiene 60 segundos. Para sumar horas y minutos, primero los expresamos en minutos.','1 h y 20 min son 80 min.',['1 h = 60 min.','60 + 20 = 80 min.'],'Para las horas usá 60, no 100.',[a(f'¿Cuántos minutos son {h} h y {m} min?',h*60+m,f'{h} × 60 = {h*60} min.\nSumamos {m}: {h*60+m} min.',[h*100+m,h+m]) for h,m in [(1,20),(2,15),(1,45),(3,10),(2,30),(4,5)]])
t='geometria_angulos'
unit('mat_ang_clases',t,'Comparar una abertura con un ángulo recto','Un ángulo es la abertura entre dos semirrectas que parten del mismo vértice. Se mide en grados. Recto: 90°. Agudo: más de 0° y menos de 90°. Obtuso: más de 90° y menos de 180°. Llano: 180°.','Un ángulo de 60° es agudo.',['Comparamos 60 con 90.','Como 0 < 60 < 90, es agudo.'],'Compará la medida con 90° y 180°.',[a(f'¿Cómo se clasifica un ángulo de {n}°?',c,f'{n}° '+s,['agudo','recto','obtuso','llano']) for n,c,s in [(60,'agudo','está entre 0° y 90°.'),(90,'recto','es exactamente 90°.'),(120,'obtuso','está entre 90° y 180°.'),(180,'llano','es exactamente 180°.'),(35,'agudo','está entre 0° y 90°.'),(150,'obtuso','está entre 90° y 180°.')]])
unit('mat_ang_complemento',t,'Dos ángulos que completan una abertura','Dos ángulos son complementarios si suman 90° y suplementarios si suman 180°. Para hallar el que falta restamos el conocido de la suma que deben completar.','Si dos ángulos suman 90° y uno mide 30°, el otro mide 60°.',['La suma buscada es 90°.','90° − 30° = 60°.'],'Identificá si deben sumar 90° o 180°.',[a(f'Dos ángulos suman {total}°. Uno mide {n}°. ¿Cuántos grados mide el otro?',total-n,f'{total} − {n} = {total-n}.\nComprobamos: {n} + {total-n} = {total}.') for total,n in [(90,30),(180,50),(90,25),(180,110),(90,40),(180,135)]])
t='geometria_triangulos'
unit('mat_tri_lados',t,'Clasificar triángulos por sus lados','Un triángulo tiene tres lados. Es equilátero si los tres son iguales, isósceles si tiene al menos dos lados iguales y escaleno si los tres son distintos. Para elegir una sola respuesta, usamos el nombre más específico.','Un triángulo de lados 4, 4 y 6 es isósceles.',['Comparamos las tres longitudes.','Tiene dos iguales y uno distinto: isósceles.'],'Contá cuántos lados tienen la misma medida.',[a(f'Un triángulo tiene lados {x}, {y} y {z} cm. Elegí el nombre más específico.',c,f'Los lados {x}, {y}, {z} tienen '+('tres medidas iguales.' if c=='equilátero' else 'dos iguales y uno distinto.' if c=='isósceles' else 'tres medidas distintas.'),['equilátero','isósceles','escaleno']) for x,y,z,c in [(4,4,6,'isósceles'),(3,3,3,'equilátero'),(3,4,5,'escaleno'),(5,5,8,'isósceles'),(7,7,7,'equilátero'),(5,6,8,'escaleno')]])
unit('mat_tri_angulos',t,'Los tres ángulos suman 180 grados','Los ángulos interiores de todo triángulo suman 180°. Si conocemos dos, sumamos sus medidas y restamos esa suma de 180°.','Un triángulo tiene ángulos de 50° y 60°. El tercero mide 70°.',['50° + 60° = 110°.','180° − 110° = 70°.'],'Restá de 180° la suma de los dos ángulos conocidos.',[a(f'Dos ángulos de un triángulo miden {x}° y {y}°. ¿Cuántos grados mide el tercero?',180-x-y,f'{x} + {y} = {x+y}.\n180 − {x+y} = {180-x-y}.') for x,y in [(50,60),(40,80),(90,35),(65,65),(30,70),(45,55)]])
t='geometria_cuadrilateros_circunferencia'
unit('mat_cuad_lados',t,'Cuatro lados y líneas paralelas','Un cuadrilátero tiene cuatro lados. Un paralelogramo tiene dos pares de lados opuestos paralelos. El cuadrado tiene cuatro lados iguales y cuatro ángulos rectos: también es rectángulo y rombo. En el cuadernillo, trapecio tiene un solo par de lados paralelos.','Todo cuadrado es también un rectángulo.',['Rectángulo significa cuatro ángulos rectos.','El cuadrado cumple esa condición y además tiene lados iguales.'],'Una figura puede pertenecer a más de una familia.',[a(q,r,s,['Sí','No']) for q,r,s in [('¿Todo cuadrado tiene cuatro ángulos rectos?','Sí','Es parte de la definición de cuadrado.'),('¿Todo rectángulo tiene los cuatro lados iguales?','No','Eso ocurre en los cuadrados; otros rectángulos tienen largo y ancho diferentes.'),('¿Un cuadrado también es un rombo?','Sí','Sus cuatro lados son iguales.'),('¿Un paralelogramo tiene dos pares de lados opuestos paralelos?','Sí','Esa condición define al paralelogramo.'),('Según el cuadernillo, ¿un trapecio tiene dos pares de lados paralelos?','No','El trapecio tiene un solo par.'),('¿Todo rombo tiene cuatro ángulos rectos?','No','Tiene cuatro lados iguales, pero sus ángulos no necesariamente son rectos.')]])
unit('mat_circ_radio',t,'Radio y diámetro','La circunferencia es la línea cuyos puntos están a la misma distancia del centro. El radio une el centro con esa línea. El diámetro une dos puntos de la circunferencia pasando por el centro y mide dos radios.','Si el radio es 3 cm, el diámetro mide 6 cm.',['Un diámetro reúne dos radios.','3 + 3 = 6 cm.'],'El diámetro mide el doble del radio.',[a(f'El radio mide {n} cm. ¿Cuántos centímetros mide el diámetro?',2*n,f'El diámetro reúne dos radios: {n} + {n} = {2*n} cm.') for n in [3,4,5,6,7,8]])
t='perimetros_simples'
unit('mat_per_rectangulo',t,'Recorrer todo el borde','El perímetro es la longitud del borde de una figura. En un rectángulo sumamos largo, ancho, largo y ancho. Se expresa en unidades de longitud, no de superficie.','Un rectángulo de 5 cm por 3 cm tiene perímetro 16 cm.',['Recorremos sus cuatro lados: 5, 3, 5, 3.','5 + 3 + 5 + 3 = 16 cm.'],'Sumá cada lado del borde una sola vez.',[a(f'Un rectángulo mide {x} cm de largo y {y} cm de ancho. ¿Cuál es su perímetro en cm?',2*(x+y),f'{x} + {y} + {x} + {y} = {2*(x+y)} cm.',[x*y,x+y,2*(x+y)+1]) for x,y in [(5,3),(6,4),(7,2),(8,3),(9,4),(10,5)]])
unit('mat_per_circunferencia',t,'Medir el borde de una circunferencia','La longitud de una circunferencia se calcula multiplicando su diámetro por pi. Usaremos pi aproximado a 3,14. Si conocemos el radio, primero lo duplicamos.','Diámetro 10 cm: longitud aproximada 31,4 cm.',['Usamos L = pi × diámetro.','3,14 × 10 = 31,4 cm.'],'Revisá si te dieron radio o diámetro.',[a(f'Una circunferencia tiene diámetro {n} cm. Usá pi = 3,14. ¿Cuál es su longitud aproximada en cm?',f'{314*n/100:.2f}'.replace('.',','),f'3,14 × {n} = '+f'{314*n/100:.2f}'.replace('.',',')+' cm.',[n*2,n*3]) for n in [10,2,4,6,8,20]])
t='perimetros_compuestos'
unit('mat_per_union',t,'Los lados compartidos quedan adentro','Al unir figuras sin superponerlas, un lado pegado deja de formar parte del borde exterior. Si sumamos sus perímetros, ese lado se contó dos veces. Restamos dos veces la longitud compartida.','Dos cuadrados de lado 3 cm unidos por un lado tienen perímetro exterior 18 cm.',['Cada cuadrado tiene perímetro 12 cm: juntos suman 24.','Quitamos dos veces el lado interno: 24 − 6 = 18 cm.'],'Recorré solo el borde exterior.',[a(f'Dos cuadrados de lado {n} cm se unen por un lado completo. ¿Cuál es el perímetro exterior en cm?',6*n,f'Los perímetros suman {8*n}.\nQuitamos el lado compartido dos veces: {8*n} − {2*n} = {6*n} cm.',[8*n,4*n]) for n in [3,4,5,6,7,8]])
unit('mat_per_faltante',t,'Encontrar un tramo que falta','Si un lado total está dividido en dos tramos, el desconocido se encuentra restando el conocido al total. Antes de calcular un perímetro compuesto, identificamos todos los tramos exteriores.','Un lado de 10 cm tiene un tramo de 4 cm: faltan 6 cm.',['El total es la suma de ambos tramos.','10 − 4 = 6 cm.'],'Los dos tramos deben sumar el lado completo.',[a(f'Un lado recto de {total} cm se divide en un tramo de {n} cm y otro desconocido. ¿Cuántos cm mide el tramo que falta?',total-n,f'{total} − {n} = {total-n}.\n{n} + {total-n} = {total} cm.') for total,n in [(10,4),(12,5),(15,6),(18,7),(20,8),(24,9)]])
t='graficos_estadisticos'
unit('mat_graf_leer',t,'Leer qué cuenta cada dato','Un gráfico o una tabla relaciona categorías con cantidades. Primero leemos qué se está contando y en qué unidad. Para buscar el mayor valor comparamos las cantidades, no el largo del nombre.','Libros leídos: Ana 3, Bruno 5, Cami 2. Bruno leyó más.',['Buscamos 3, 5 y 2 libros.','5 es la mayor cantidad; corresponde a Bruno.'],'Leé los nombres y sus cantidades antes de comparar.',[a(f'Libros leídos: Ana {x}, Bruno {y}, Cami {z}. ¿Quién leyó más?',['Ana','Bruno','Cami'][[x,y,z].index(max(x,y,z))],f'Comparamos {x}, {y} y {z}. La mayor cantidad es {max(x,y,z)}.',['Ana','Bruno','Cami']) for x,y,z in [(3,5,2),(6,2,4),(4,3,7),(8,9,5),(7,4,3),(5,6,8)]])
unit('mat_graf_escala',t,'Una marca puede valer más de uno','En un pictograma cada símbolo puede representar varias unidades. Leemos la clave antes de contar. Si cada símbolo vale dos libros, cuatro símbolos representan ocho libros.','4 símbolos de 2 libros cada uno representan 8 libros.',['Contamos 4 símbolos.','4 × 2 = 8 libros.'],'Buscá cuánto vale cada símbolo en la clave.',[a(f'En un pictograma, cada símbolo representa {k} libros. Hay {n} símbolos completos. ¿Cuántos libros representan?',k*n,f'{n} símbolos × {k} libros = {k*n} libros.',[n,k+n]) for n,k in [(4,2),(3,5),(6,2),(5,3),(7,4),(8,5)]])
t='proporcionalidad_regla_3'
unit('mat_prop_unidad',t,'Primero averiguamos cuánto vale uno','En una relación directamente proporcional, cada unidad conserva el mismo valor. Si tres cuadernos cuestan 600 pesos, uno cuesta 600 ÷ 3. No hay descuentos ni cargos extra en estos ejercicios.','3 cuadernos cuestan $600: uno cuesta $200.',['Dividimos el precio total entre la cantidad.','600 ÷ 3 = 200 pesos por cuaderno.'],'Buscá el valor de una unidad.',[a(f'{n} cuadernos iguales cuestan ${n*p}, sin descuentos. ¿Cuántos pesos cuesta uno?',p,f'{n*p} ÷ {n} = {p} pesos por cuaderno.',[n*p,p+n]) for n,p in [(3,200),(4,150),(5,120),(2,250),(6,100),(8,50)]])
unit('mat_prop_otro_total',t,'Del valor de uno a otra cantidad','Después de hallar el valor de una unidad, lo multiplicamos por la nueva cantidad. Este método sirve cuando el valor por unidad es constante.','3 cuadernos cuestan $600. Cinco cuestan $1000.',['Uno cuesta 600 ÷ 3 = 200.','Cinco cuestan 5 × 200 = 1000.'],'Primero dividí para llegar a uno; después multiplicá.',[a(f'{n} cuadernos cuestan ${n*p}. Al mismo precio por unidad, ¿cuántos pesos cuestan {m}?',m*p,f'Uno cuesta {n*p} ÷ {n} = {p}.\n{m} cuestan {m} × {p} = {m*p}.',[n*p,m*p+p]) for n,p,m in [(3,200,5),(4,150,6),(5,120,3),(2,250,4),(6,100,9),(8,50,7)]])
t='secuencias_aritmeticas'
unit('mat_sec_salto',t,'Repetir siempre el mismo salto','Una secuencia aritmética cambia sumando o restando siempre la misma cantidad. Calculamos la diferencia entre términos vecinos y la comprobamos en los demás.','4, 7, 10, 13 continúa con 16.',['7 − 4 = 3 y 10 − 7 = 3.','Sumamos el mismo salto: 13 + 3 = 16.'],'Comprobá que el salto se repite antes de continuar.',[a(f'Seguí sumando siempre lo mismo: {s}, {s+d}, {s+2*d}, {s+3*d}. ¿Qué número sigue?',s+4*d,f'El salto es +{d}.\n{s+3*d} + {d} = {s+4*d}.') for s,d in [(4,3),(2,4),(5,2),(7,5),(3,6),(10,7)]])
unit('mat_sec_restar',t,'Secuencias que bajan','Una secuencia también puede repetir una resta. Si los términos bajan de cuatro en cuatro, restamos cuatro al último término. No cambiamos a una suma porque veamos números más pequeños.','25, 21, 17, 13 continúa con 9.',['25 − 21 = 4 y 21 − 17 = 4.','13 − 4 = 9.'],'Observá si la secuencia sube o baja.',[a(f'Seguí restando siempre lo mismo: {s}, {s-d}, {s-2*d}, {s-3*d}. ¿Qué número sigue?',s-4*d,f'Cada paso resta {d}.\n{s-3*d} − {d} = {s-4*d}.') for s,d in [(25,4),(30,5),(40,6),(35,3),(50,7),(60,8)]])
t='secuencias_geometricas_fibonacci'
unit('mat_sec_factor',t,'Repetir una multiplicación','En algunas secuencias cada término se obtiene multiplicando el anterior por el mismo número. La diferencia entre términos puede cambiar, pero el factor se conserva.','2, 4, 8, 16 continúa con 32.',['Cada término es el anterior multiplicado por 2.','16 × 2 = 32.'],'Probá el mismo factor en todos los pasos.',[a(f'Cada término se multiplica por {k}: {s}, {s*k}, {s*k*k}. ¿Qué número sigue?',s*k**3,f'{s*k*k} × {k} = {s*k**3}.') for s,k in [(2,2),(3,2),(1,3),(4,2),(2,3),(5,2)]])
unit('mat_sec_fibonacci',t,'Sumar los dos anteriores','Otra regla consiste en sumar los dos términos anteriores para obtener el siguiente. Necesitamos conservar ambos, no solo el último. La secuencia de Fibonacci usa esta regla comenzando con 1 y 1.','1, 1, 2, 3, 5 continúa con 8.',['2 + 3 = 5.','Para seguir usamos 3 + 5 = 8.'],'Marcá los últimos dos términos y sumalos.',[a(f'Cada término nuevo suma los dos anteriores: {x}, {y}, {x+y}, {x+2*y}. ¿Qué número sigue?',2*x+3*y,f'Los últimos son {x+y} y {x+2*y}.\n{x+y} + {x+2*y} = {2*x+3*y}.') for x,y in [(1,1),(1,2),(2,3),(3,4),(2,5),(4,5)]])
t='secuencias_alfanumericas_y_figuras'
unit('mat_sec_ciclo',t,'Un bloque que se repite','En un patrón repetitivo se repite un bloque completo, como rojo, azul, verde. Para continuar buscamos dónde termina el bloque y volvemos a empezar.','Rojo, azul, verde, rojo, azul continúa con verde.',['El bloque es rojo, azul, verde.','Después de azul viene verde.'],'Separá el patrón en bloques iguales.',[a(f'Repetimos el bloque {", ".join(block)}. La fila termina en {block[(n-1)%len(block)]}, posición {n}. ¿Qué sigue?',block[n%len(block)],f'La posición siguiente en el bloque corresponde a {block[n%len(block)]}.',block) for block,n in [(['rojo','azul','verde'],5),(['círculo','cuadrado'],3),(['sol','luna','estrella'],6),(['A','B','C'],4),(['grande','pequeño'],4),(['uno','dos','tres'],7)]])
unit('mat_sec_dos_reglas',t,'Separar letras y números','Una secuencia puede combinar dos reglas. Leemos las letras por un lado y los números por otro. En A1, B3, C5, las letras avanzan una posición y los números aumentan dos.','A1, B3, C5 continúa con D7.',['A, B, C continúa con D.','1, 3, 5 continúa con 7. Juntamos D7.'],'Seguí cada regla por separado y después unilas.',[a(f'Las letras avanzan una posición; los números suman {d}. A{s}, B{s+d}, C{s+2*d}. ¿Qué sigue?',f'D{s+3*d}',f'Después de C viene D; {s+2*d} + {d} = {s+3*d}.',[f'C{s+3*d}',f'D{s+2*d}']) for s,d in [(1,2),(2,3),(3,4),(4,5),(5,2),(6,3)]])
t='ecuaciones_con_imagenes_2_incognitas'
unit('mat_igual_simbolo',t,'El mismo símbolo conserva su valor','En estos acertijos, el mismo símbolo representa siempre la misma cantidad. Dos soles que suman 12 valen 6 cada uno. La igualdad indica que ambos lados tienen el mismo valor.','sol + sol = 12: cada sol vale 6.',['Hay dos cantidades iguales que suman 12.','12 ÷ 2 = 6; comprobamos 6 + 6 = 12.'],'Contá cuántas veces aparece el mismo símbolo.',[a(f'sol + sol = {2*n}. ¿Cuánto vale un sol?',n,f'Dos soles suman {2*n}; uno vale {2*n} ÷ 2 = {n}.') for n in [6,4,5,7,8,9]])
unit('mat_igual_dos',t,'Reemplazar lo conocido para hallar lo que falta','Si encontramos el valor de un símbolo, podemos reemplazarlo en otra igualdad. Después buscamos cuánto falta para completar el total. Comprobamos los dos resultados.','sol + sol = 12 y sol + luna = 10: luna vale 4.',['Cada sol vale 12 ÷ 2 = 6.','6 + luna = 10; entonces luna = 10 − 6 = 4.'],'Primero resolvé el símbolo repetido; después reemplazalo.',[a(f'sol + sol = {2*x}; sol + luna = {x+y}. ¿Cuánto vale luna?',y,f'Sol = {2*x} ÷ 2 = {x}.\nLuna = {x+y} − {x} = {y}.',[x,x+y]) for x,y in [(6,4),(4,7),(5,3),(7,2),(8,5),(9,6)]])
